#include <iostream>

#include <noarr/structures_extended.hpp>        // structures, layout transforms
#include <noarr/traversers.hpp>                 // traverser
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, N, TSTEPS, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions
#include "seidel-2d.hpp"

using num_t = DATA_TYPE;

namespace {

// Basic 2D layout protos
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A is an N x N matrix indexed by (i, j)
	// layout: i = row index (outer), j = column index (inner, contiguous)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// ------------------------------------------------------------------
	// Tuning parameters for traversal
	// ------------------------------------------------------------------
	// Block sizes for cache-friendly tiling. These are compile-time
	// constants so they are easy to tune for a given machine.
	//
	// - BLOCK_I: tile size in the (row) 'i' dimension
	// - BLOCK_J: tile size in the (column) 'j' dimension
	//
	// They do NOT need to divide the problem size; we use
	// `into_blocks_dynamic` which handles partial tiles correctly.
	static constexpr std::size_t BLOCK_I = 32;
	static constexpr std::size_t BLOCK_J = 64;
} tuning;


// Array initialization
// A: i x j
void init_array(auto A) {
	using namespace noarr;

	// grid size inferred from the structure
	auto n = A | get_length<'i'>();
	auto n_val = static_cast<num_t>(n);

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(2))
		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// This is a 2D 9-point Gauss–Seidel stencil applied in-place:
//
//   A[i,j] = ( A[i-1,j-1] + A[i-1,j] + A[i-1,j+1]
//            + A[i  ,j-1] + A[i  ,j] + A[i  ,j+1]
//            + A[i+1,j-1] + A[i+1,j] + A[i+1,j+1] ) / 9
//
// for i,j in [1, n-2] and repeated for `tsteps` time steps.
//
// Optimizations compared to the baseline:
//
// 1. **Blocked / tiled traversal** in both dimensions using
//    `noarr::into_blocks_dynamic` + `noarr::hoist`.
//    This improves cache locality by working on rectangular tiles
//    of size (BLOCK_I x BLOCK_J). Edge tiles that do not fit the
//    block size are handled automatically and correctly.
//
// 2. **Division hoisting**: we precompute the multiplicative inverse
//    of 9 so the inner loop uses a multiplication instead of a division.
//    (Compilers can do this, but we make it explicit.)
//
// 3. All iteration is expressed using Noarr traversers, as required.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	auto n_i = A | get_length<'i'>();
	auto n_j = A | get_length<'j'>();

	// Precompute 1/9 to replace division by a multiplication.
	const num_t one_ninth = num_t(1.0) / num_t(9.0);

	// Interior region (exclude boundaries):
	// i, j ∈ [1, n-2]. We express this as a pair of slices:
	//   - start = 1
	//   - length = n - 2
	//
	// IMPORTANT:
	//   `slice` is applied via `order`, so the state seen inside the
	//   lambda still uses the ORIGINAL global indices in 'i' and 'j'
	//   (1 .. n-2), which is exactly what `neighbor()` expects.
	auto interior =
		slice<'i'>(std::size_t(1), n_i - 2) ^
		slice<'j'>(std::size_t(1), n_j - 2);

	// Block sizes (possibly tuned per-architecture)
	const std::size_t bi = tuning::BLOCK_I;
	const std::size_t bj = tuning::BLOCK_J;

	// ------------------------------------------------------------------
	// Blocking configuration
	// ------------------------------------------------------------------
	//
	// We split both 'i' and 'j' into blocks using `into_blocks_dynamic`.
	// This introduces, conceptually, these dimensions:
	//
	//   - For 'i':
	//       'I'  : block index in i (major dimension)
	//       'i'  : index within the block (minor dimension)
	//       'r_i': "is-present" flag for the dynamic tail block
	//
	//   - For 'j':
	//       'J'  : block index in j (major dimension)
	//       'j'  : index within the block (minor dimension)
	//       'r_j': "is-present" flag for the dynamic tail block
	//
	// The dynamic variant automatically handles the case where the
	// interior length is not a multiple of the block size.
	//
	// We then hoist 'J' and 'I' so that the traversal order becomes:
	//   outer blocks in i ('I'), then blocks in j ('J'),
	//   then the fine-grained indices inside each block.
	//
	// NOTE:
	//   Because we apply these proto-structures via `.order(...)`
	//   on the traverser (not by changing A's type), the *state*
	//   we see in the lambda still only contains the original
	//   dimensions 'i' and 'j'. The extra block dimensions are
	//   used solely to guide the traversal order.
	auto blocked =
		into_blocks_dynamic<'i', 'I', 'i', 'r'>(bi) ^
		into_blocks_dynamic<'j', 'J', 'j', 's'>(bj) ^
		// Make block columns ('J') outer and block rows ('I') just
		// inside them to get a 2D block traversal:
		hoist<'J'>() ^
		hoist<'I'>();

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Traverse only the interior points in a blocked / tiled
		// fashion. Thanks to `.order(interior ^ blocked)`, the
		// traversal order is:
		//   for each block in J
		//     for each block in I
		//       for each interior point (i, j) inside that block
		//
		// But the `state` still only carries the global 'i' and 'j'
		// indices, which we can freely use with `neighbor()`.
		traverser(A)
			.order(interior ^ blocked)
			.for_each([&](auto state) {
				auto s = state; // shorthand

				// Build states for all 8 neighbors and the center.
				// `neighbor` safely handles negative/positive deltas
				// in each dimension and returns a new state.
				auto s_im1_jm1 = neighbor<'i', 'j'>(s, -1, -1);
				auto s_im1_j   = neighbor<'i'>(s, -1);
				auto s_im1_jp1 = neighbor<'i', 'j'>(s, -1, +1);

				auto s_i_jm1   = neighbor<'j'>(s, -1);
				auto s_i_j     = s;
				auto s_i_jp1   = neighbor<'j'>(s, +1);

				auto s_ip1_jm1 = neighbor<'i', 'j'>(s, +1, -1);
				auto s_ip1_j   = neighbor<'i'>(s, +1);
				auto s_ip1_jp1 = neighbor<'i', 'j'>(s, +1, +1);

				num_t sum =
					A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
					A[s_i_jm1]   + A[s_i_j]   + A[s_i_jp1] +
					A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

				// Use multiplication by precomputed 1/9 instead of division.
				A[s_i_j] = sum * one_ninth;
			});
	}
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// configure layout and lengths
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_seidel_2d(tsteps, A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional, to prevent dead-code elimination / check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
