		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// Optimized version:
//  - Still performs an in-place 9‑point Gauss–Seidel sweep.
//  - Traversal of the spatial grid is *blocked along the i-dimension* using
//    `into_blocks_static`. This preserves the original lexicographic order
//    (i outer, j inner), which is essential for Gauss–Seidel semantics,
//    but improves cache behavior when N is large.
//  - The blocked traversal is expressed entirely using Noarr traversers
//    (`for_dims` + `for_each`) as required.
//  - A precomputed reciprocal of 9 is used to avoid repeated divisions.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	auto n_i = A | get_length<'i'>();
	auto n_j = A | get_length<'j'>();

	// Degenerate cases: nothing to do
	if (tsteps <= 0 || n_i <= 2 || n_j <= 2)
		return;

	// Precompute 1/9 once; used for every update
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	// Proto-structure describing blocking in the 'i' dimension.
	//
	// We use into_blocks_static<'i','b','I','i'>:
	//  - 'i'  : original row dimension to be split
	//  - 'b'  : "body/border" tuple-like dimension (0 = body, 1 = border)
	//  - 'I'  : block index along i (major index within body/border)
	//  - 'i'  : row index inside a block (minor index)
	//
	// The block size is tuning::block_i. Using into_blocks_static ensures
	// the *body* part contains only full blocks, while the *border* part
	// contains the (at most block_i-1) remaining rows. Importantly, the
	// global order of rows is still 1,2,...,n_i-2, which keeps the
	// Gauss–Seidel update order unchanged.
	constexpr auto block_i_proto =
		into_blocks_static<'i', 'b', 'I', 'i'>(noarr::lit<tuning::block_i>);

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Restrict traversal to interior points:
		//   i, j in [1, n-2]
		// The slice is applied through order(), so the states seen in the
		// lambda still use the *original* indices (1 .. n-2), which keeps
		// neighbor() semantics simple and unchanged.
		auto interior_slices =
			slice<'i'>(1, n_i - 2) ^
			slice<'j'>(1, n_j - 2);

		// Apply interior restriction and i-blocking to the traverser.
		// The resulting logical dimensions (for use with for_dims) are:
		//   'b' (body/border), 'I' (block of rows), and within each block
		//   the original 'i' and 'j' dimensions.
		auto trav =
			traverser(A).order(interior_slices ^ block_i_proto);

		// Iterate first over the body ('b' == 0) and then over the border
		// ('b' == 1) blocks.  For each combination of (b, I) we run a full
		// Gauss–Seidel sweep over the rows in that tile:
		//
		//   - for_dims<'b','I'> preserves the global row order:
		//       rows 1..block_i, then block_i+1..2*block_i, ..., then any
		//       remaining rows in the border tile. This is exactly the same
		//       lexicographic order as the original "for i / for j" loops.
		//
		//   - trav_block.for_each([state]) then iterates 'i' (row) and 'j'
		//     (column) inside the current tile in the default order
		//     (i outer, j inner), matching the original traversal.
		trav.template for_dims<'b', 'I'>([&](auto trav_block) {
			trav_block.for_each([&](auto state) {
				auto s = state; // original ('i','j') indices in the interior

				// Build states for the 8 neighbors and the center.
				// Because we sliced to [1, n-2] for both dimensions,
				// all these neighbors are guaranteed to be inside bounds.
				auto s_im1_jm1 = neighbor<'i', 'j'>(s, -1, -1);
				auto s_im1_j   = neighbor<'i'>(s, -1);
				auto s_im1_jp1 = neighbor<'i', 'j'>(s, -1, +1);

				auto s_i_jm1   = neighbor<'j'>(s, -1);
				auto s_i_j     = s;
				auto s_i_jp1   = neighbor<'j'>(s, +1);

				auto s_ip1_jm1 = neighbor<'i', 'j'>(s, +1, -1);
				auto s_ip1_j   = neighbor<'i'>(s, +1);
				auto s_ip1_jp1 = neighbor<'i', 'j'>(s, +1, +1);

				num_t sum =
					A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
					A[s_i_jm1]   + A[s_i_j]   + A[s_i_jp1] +
					A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

				A[s_i_j] = sum * inv9;
			});
		});
	}
	#pragma endscop
