// include common definitions (DATA_TYPE, N, TSTEPS, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions
#include "seidel-2d.hpp"

using num_t = DATA_TYPE;

namespace {

// Layout helpers for the two spatial dimensions
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Tunable blocking parameter for the i-dimension (rows).
// This controls how many rows are processed together in the "blocked" part.
// Semantics of Gauss–Seidel are preserved because we still visit rows
// in strictly increasing order; we only group them into larger chunks.
constexpr std::size_t I_BLOCK = 64;

struct tuning {
	// A is an N x N matrix indexed by (i, j)
	// layout: i = row index (outer), j = column index (inner)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;


// Array initialization
// A: i x j
void init_array(auto A) {
	using namespace noarr;

	// grid size inferred from the structure
	std::size_t n = A | get_length<'i'>();
	auto n_val = static_cast<num_t>(n);

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(2))
		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// Optimization strategy (while preserving original Gauss–Seidel semantics):
// - We keep the sweep order in (i,j) lexicographic order, which is crucial
//   for in-place Gauss–Seidel.
// - We introduce a tunable blocking in the i-dimension only.  The i-sweep is
//   split into a "blocked" part that is a multiple of I_BLOCK rows and a
//   "tail" part with the remaining rows.  Rows are still processed in strictly
//   increasing order, so the numerical result is unchanged.
// - We pre-build Noarr proto-structures for the interior region and re-use
//   them in each time step to avoid reconstructing them in every iteration.
// - The actual stencil update is factored into a small lambda that takes a
//   Noarr state and uses only A[state]-style accesses.
//
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	std::size_t n_i = A | get_length<'i'>();
	std::size_t n_j = A | get_length<'j'>();

	// We update only the interior: i, j in [1, n-2]
	// Guard against degenerate cases, although PolyBench uses n >= 3.
	std::size_t interior_i = (n_i > 2u) ? (n_i - 2u) : 0u;
	std::size_t interior_j = (n_j > 2u) ? (n_j - 2u) : 0u;

	if (interior_i == 0 || interior_j == 0 || tsteps <= 0)
		return;

	// Split the i-range into a blocked "body" part and a remaining "tail".
	// The body length is the largest multiple of I_BLOCK not exceeding
	// the interior length.
	const std::size_t body_i = (interior_i / I_BLOCK) * I_BLOCK;
	const std::size_t tail_i = interior_i - body_i;

	// Common slice of the full interior in j (1 .. n_j-2)
	const auto slice_j_all = slice<'j'>(1, interior_j);

	// Slices for the i-dimension:
	// - body: rows 1 .. body_i
	// - tail: rows (1 + body_i) .. (1 + body_i + tail_i - 1)
	const auto slice_i_body = slice<'i'>(1, body_i);
	const auto slice_i_tail = slice<'i'>(1 + body_i, tail_i);

	// Precompute 1/9 as a constant for the stencil
	const num_t one_ninth = num_t(1.0) / num_t(9.0);

	// Local lambda that performs the 9-point Gauss–Seidel update for a single
	// interior point specified by 'state'. The state carries the original
	// (i,j) indices because we apply slicing/blocking via traverser.order().
	auto update_point = [&](auto state) {
		auto s = state;

		// Neighbors in i-direction
		auto s_im1_j = neighbor<'i'>(s, -1);
		auto s_ip1_j = neighbor<'i'>(s, +1);

		// Neighbors in j-direction
		auto s_i_jm1 = neighbor<'j'>(s, -1);
		auto s_i_jp1 = neighbor<'j'>(s, +1);

		// Diagonals: combine row shifts with column shifts
		auto s_im1_jm1 = neighbor<'j'>(s_im1_j, -1);
		auto s_im1_jp1 = neighbor<'j'>(s_im1_j, +1);

		auto s_ip1_jm1 = neighbor<'j'>(s_ip1_j, -1);
		auto s_ip1_jp1 = neighbor<'j'>(s_ip1_j, +1);

		// Center
		auto s_i_j = s;

		num_t sum =
			A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
			A[s_i_jm1]   + A[s_i_j]   + A[s_i_jp1] +
			A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

		A[s_i_j] = sum * one_ninth;
	};

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// 1) Blocked part in i: rows 1 .. body_i, processed in chunks of
		//    height I_BLOCK. We use into_blocks on 'i' only. This introduces
		//    a synthetic block index 'I' but, thanks to traverser.order(),
		//    the state seen inside update_point still uses the original
		//    indices (i,j). The effective visit order of (i,j) is identical
		//    to the simple lexicographic sweep.
		if (body_i > 0) {
			auto trav_body =
				traverser(A)
					.order(
						slice_i_body ^
						slice_j_all ^
						into_blocks<'i', 'I', 'i'>(I_BLOCK)
					);

			// Outer loop over blocks in i ('I'), inner loops over the rows
			// inside the block and over j. This forms the loop nest:
			//   for (I) for (i in block I) for (j)
			// which preserves the original (i,j) lexicographic ordering.
			trav_body.template for_dims<'I'>([&](auto trav_block) {
				trav_block.for_each([&](auto state) {
					update_point(state);
				});
			});
		}

		// 2) Tail rows that do not fit into a full I_BLOCK-sized chunk:
		//    rows (1 + body_i) .. (1 + body_i + tail_i - 1).
		//    This is a plain lexicographic sweep over the remaining rows,
		//    again preserving the original Gauss–Seidel order.
		if (tail_i > 0) {
			auto trav_tail =
				traverser(A)
					.order(
						slice_i_tail ^
						slice_j_all
					);

			trav_tail.for_each([&](auto state) {
				update_point(state);
			});
		}
	}
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// configure layout and lengths
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_seidel_2d(tsteps, A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional, to prevent dead-code elimination / check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
