#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, N, TSTEPS, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions
#include "seidel-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A is an N x N matrix indexed by (i, j)
	// layout: i = row index (outer), j = column index (inner)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// Tunable spatial blocking factor in the i (row) dimension for the Seidel sweep.
	// Must be a positive compile-time constant. The kernel handles non-multiples of
	// this size explicitly, so N can be arbitrary.
	static constexpr std::size_t block_i = 32;
} tuning;


// Array initialization
// A: i x j
void init_array(auto A) {
	using namespace noarr;

	// grid size inferred from the structure
	auto n = A | get_length<'i'>();
	auto n_val = static_cast<num_t>(n);

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(2))
		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// Optimization strategy:
// ----------------------
// - Keep the in-place Gauss–Seidel update semantics exactly the same: for each
//   time-step t, visit all interior points (i,j) with i,j in [1, n-2] in the
//   same lexicographic order (i-major, j-minor) as the original code.
// - Apply blocking only in the i-dimension, *via* a traverser `order(...)` and
//   `noarr::into_blocks`, so the visible index state in the lambda is still
//   expressed in the original ('i','j') coordinates. This preserves the
//   neighbor relationships and update order, while improving spatial locality
//   and cache reuse in the row dimension.
// - The block size is a compile-time constant (tuning::block_i). Edge cases
//   where the interior height is not divisible by the block size are handled
//   explicitly by splitting the traversal into:
//     (1) a blocked prefix of rows whose count is a multiple of block_i
//     (2) a non-blocked tail with the remaining interior rows.
//
// The resulting per-timestep order of updated points is bitwise identical to
// the original "for i in 1..n-2, for j in 1..n-2" loop nest.
//
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	const std::size_t n_i = A | get_length<'i'>();
	const std::size_t n_j = A | get_length<'j'>();

	if (n_i <= 2 || n_j <= 2 || tsteps <= 0)
		return; // no interior points

	// Number of interior points in each dimension:
	// i, j in [1, n-2]  =>  count = n-2
	const std::size_t interior_i_len = n_i - 2;
	const std::size_t interior_j_len = n_j - 2;

	// Compile-time tunable block size in the i-dimension
	constexpr std::size_t block_i = tuning::block_i;

	// Largest multiple of block_i fitting into interior_i_len
	const std::size_t full_i_len  = (interior_i_len / block_i) * block_i;
	const std::size_t tail_i_len  = interior_i_len - full_i_len;

	// Precompute 1/9 to avoid repeated division in the inner loop
	const num_t one_ninth = num_t(1.0) / num_t(9.0);

	// Base traverser over the full array A (no slicing yet)
	auto base_trav = traverser(A);

	// Point-wise update kernel, used from both the blocked and the tail traversals.
	// The state always carries the *original* indices in 'i' and 'j' (in the
	// global coordinate system), because we apply blocking via traverser::order().
	auto update_point = [&](auto state) noexcept {
		auto s = state;

		// Build states for all 8 neighbors and the center
		auto s_im1_jm1 = neighbor<'i', 'j'>(s, -1, -1);
		auto s_im1_j   = neighbor<'i'>(s, -1);
		auto s_im1_jp1 = neighbor<'i', 'j'>(s, -1, +1);

		auto s_i_jm1   = neighbor<'j'>(s, -1);
		auto s_i_j     = s;
		auto s_i_jp1   = neighbor<'j'>(s, +1);

		auto s_ip1_jm1 = neighbor<'i', 'j'>(s, +1, -1);
		auto s_ip1_j   = neighbor<'i'>(s, +1);
		auto s_ip1_jp1 = neighbor<'i', 'j'>(s, +1, +1);

		num_t sum =
			A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
			A[s_i_jm1]   + A[s_i_j]   + A[s_i_jp1]   +
			A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

		A[s_i_j] = sum * one_ninth;
	};

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {

		// 1) Blocked prefix in the i-dimension:
		//    - rows i in [1, 1 + full_i_len - 1]
		//    - j in [1, n_j - 2]
		//    These rows are further split into blocks of size block_i using
		//    into_blocks<'i','I','i'>(block_i) applied via order().
		if (full_i_len != 0) {
			base_trav
				.order(
					// Restrict to the interior region in i and j
					slice<'i'>(1, full_i_len) ^
					slice<'j'>(1, interior_j_len) ^
					// Split the interior i-range into blocks of size block_i.
					// Because full_i_len is a multiple of block_i, the last
					// block is always full, so we can use plain into_blocks.
					//
					// into_blocks is applied through order(), therefore the
					// index state seen in update_point still only contains
					// 'i' and 'j' in the original coordinate system.
					noarr::into_blocks<'i', 'I', 'i'>(noarr::lit<block_i>)
				)
				.for_each(update_point);
		}

		// 2) Tail region in the i-dimension, if interior_i_len is not
		//    divisible by block_i:
		//    - rows i in [1 + full_i_len, n_i - 2]
		//    - j in [1, n_j - 2]
		//    This part is traversed without blocking, preserving the same
		//    lexicographic (i-major, j-minor) order as the original code.
		if (tail_i_len != 0) {
			base_trav
				.order(
					slice<'i'>(1 + full_i_len, tail_i_len) ^
					slice<'j'>(1, interior_j_len)
				)
				.for_each(update_point);
		}
	}
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// configure layout and lengths
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_seidel_2d(tsteps, A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional, to prevent dead-code elimination / check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
