#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, N, TSTEPS, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions
#include "seidel-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A is an N x N matrix indexed by (i, j)
	// layout: i = row index (outer), j = column index (inner)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// Tunable constants for potential future blocking / vectorization.
	// They are kept here to make it easy to experiment with tiling strategies
	// without touching the rest of the code.
	static constexpr std::size_t block_i = 32;
	static constexpr std::size_t block_j = 32;
} tuning;


// Array initialization
// A: i x j
void init_array(auto A) {
	using namespace noarr;

	// grid size inferred from the structure
	auto n = A | get_length<'i'>();
	auto n_val = static_cast<num_t>(n);

	// Default traversal order already respects the layout:
	// outer loop over 'i' (rows), inner loop over 'j' (columns).
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(2))
		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// This implements the standard PolyBench 2D Seidel (Gauss–Seidel) stencil:
//   A[i][j] = (sum of 3x3 neighborhood around (i,j)) / 9
// updated in-place, in lexicographic (i, j) order for each time step.
//
// Optimizations compared to the baseline:
//
// 1. The constant 1/9 is precomputed outside the loops and the division
//    is replaced by a multiplication by `inv9`. Compilers usually do this,
//    but we make it explicit.
//
// 2. Neighbor states are constructed in a reuse-friendly way:
//    - first we build the four axial neighbors (i±1, j) and (i, j±1),
//    - then derive diagonal neighbors from those by shifting only in 'j'.
//    This turns the four original 2D neighbor() calls into four 1D calls
//    on already-shifted states, slightly reducing index manipulation.
//
// 3. The traversal still uses noarr::traverser and operates only on the
//    interior region [1, n-2] x [1, n-2], preserving the exact update
//    order (row-major: i outer, j inner) and therefore the original
//    Gauss–Seidel semantics and numerical results.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	auto n_i = A | get_length<'i'>();
	auto n_j = A | get_length<'j'>();

	// Precompute 1/9 as a constant and use a multiplication instead of a division.
	// This is safe for all standard floating-point DATA_TYPEs.
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Traverse only the interior points: i, j in [1, n-2]
		// `slice` is applied via `order`, so the state seen in the lambda
		// still uses the original indices (1 .. n-2), suitable for neighbor().
		traverser(A)
			.order(slice<'i'>(1, n_i - 2) ^ slice<'j'>(1, n_j - 2))
			.for_each([&](auto state) {
				// Current interior cell (i, j)
				auto s = state;

				// First compute axial neighbors:
				//   (i-1, j), (i+1, j), (i, j-1), (i, j+1)
				// These are used directly and also serve as a base for the diagonals.
				auto s_im1_j = neighbor<'i'>(s, -1);
				auto s_ip1_j = neighbor<'i'>(s, +1);
				auto s_i_jm1 = neighbor<'j'>(s, -1);
				auto s_i_jp1 = neighbor<'j'>(s, +1);

				// Now derive diagonal neighbors by shifting only in 'j'.
				// This avoids calling neighbor() with both 'i' and 'j' at once.
				auto s_im1_jm1 = neighbor<'j'>(s_im1_j, -1); // (i-1, j-1)
				auto s_im1_jp1 = neighbor<'j'>(s_im1_j, +1); // (i-1, j+1)
				auto s_ip1_jm1 = neighbor<'j'>(s_ip1_j, -1); // (i+1, j-1)
				auto s_ip1_jp1 = neighbor<'j'>(s_ip1_j, +1); // (i+1, j+1)

				// Sum over the 3x3 stencil centered at (i, j).
				const num_t sum =
					A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
					A[s_i_jm1]   + A[s]       + A[s_i_jp1]   +
					A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

				// In-place Gauss–Seidel update
				A[s] = sum * inv9;
			});
	}
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// configure layout and lengths
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_seidel_2d(tsteps, A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional, to prevent dead-code elimination / check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
